.mf-chat-head{padding:16px 18px;background:linear-gradient(135deg,#1877f2,#0b57d0);color:#fff;display:flex;align-items:center;justify-content:space-between}.mf-chat-head button{border:0;background:rgba(255,255,255,.18);color:#fff;border-radius:50%;width:34px;height:34px}
