.mf-chat-body{flex:1;overflow-y:auto;background:#fff}.mf-chat-section-title{font-size:.76rem;text-transform:uppercase;letter-spacing:.06em;color:#6b7280;font-weight:700;padding:12px 16px 6px}.mf-chat-row{display:flex;align-items:center;padding:10px 14px;cursor:pointer;border:0;background:#fff;width:100%;text-align:left}.mf-chat-row:hover{background:#f4f7fb}.mf-chat-avatar{width:42px;height:42px;border-radius:50%;background:#e7f0ff;color:#1877f2;display:flex;align-items:center;justify-content:center;font-weight:700;flex:0 0 42px;position:relative}.mf-chat-avatar img{width:42px;height:42px;border-radius:50%;object-fit:cover}.mf-chat-presence{position:absolute;width:12px;height:12px;border-radius:50%;border:2px solid #fff;right:-1px;bottom:1px}.mf-chat-presence.online{background:#31a24c}.mf-chat-presence.away{background:#f7b928}.mf-chat-meta{min-width:0;flex:1;margin-left:11px}.mf-chat-name{font-weight:600;color:#17202a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.mf-chat-sub{font-size:.78rem;color:#6b7280;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.mf-chat-count{background:#1877f2;color:#fff;border-radius:999px;min-width:20px;height:20px;padding:0 6px;display:flex;align-items:center;justify-content:center;font-size:.7rem}
.mf-chat-conversation{display:none;flex:1;min-height:0;flex-direction:column}.mf-chat-conversation.open{display:flex}.mf-chat-list.hidden{display:none}.mf-chat-thread-head{padding:10px 12px;border-bottom:1px solid #e5e7eb;display:flex;align-items:center}.mf-chat-thread-head button{border:0;background:transparent;color:#1877f2;font-size:1.1rem}.mf-chat-messages{flex:1;overflow-y:auto;padding:14px;background:#f7f8fa}.mf-chat-bubble{max-width:80%;padding:9px 12px;border-radius:16px;background:#e4e6eb;margin:5px 0;color:#17202a;word-break:break-word}.mf-chat-bubble.mine{margin-left:auto;background:#1877f2;color:#fff}.mf-chat-sender{font-size:.68rem;font-weight:700;margin-bottom:2px}.mf-chat-time{font-size:.64rem;opacity:.72;margin-top:3px}.mf-chat-compose{padding:10px;border-top:1px solid #e5e7eb;display:flex;gap:8px}.mf-chat-compose input{flex:1;border:0;background:#f0f2f5;border-radius:20px;padding:9px 13px;outline:0}.mf-chat-compose button{border:0;border-radius:50%;width:38px;height:38px;background:#1877f2;color:#fff}.mf-chat-empty{padding:35px 20px;text-align:center;color:#6b7280}.mf-chat-footer{border-top:1px solid #e5e7eb;padding:9px;text-align:center;font-size:.8rem}
